/** @brief  Nonlinear transformation S of the standard. */
static void transform_s(uint8_t block[GOST_KUZNYECHIK_BLOCK])
{
    for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
        block[i] = kuznyechik_sbox[block[i]];
    }
}

/** @brief  Inverse nonlinear transformation S^-1. */
static void transform_s_inverse(uint8_t block[GOST_KUZNYECHIK_BLOCK])
{
    for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
        block[i] = kuznyechik_sbox_inverse[block[i]];
    }
}

/**
 *  @brief  One round R of the linear transform.
 *
 *  The block shifts one byte to the right (byte 15 wraps to byte 0 is
 *  NOT the case here: byte i takes the value of byte i - 1, and byte 0
 *  becomes the linear combination of the shifted values).
 */
static void transform_r(const uint8_t in[GOST_KUZNYECHIK_BLOCK], uint8_t out[GOST_KUZNYECHIK_BLOCK])
{
    uint8_t mixed = kuznyechik_linear_table[0][in[15U]];
    for (unsigned i = 1; i < GOST_KUZNYECHIK_BLOCK; i++) {
        out[i] = in[i - 1U];
        mixed ^= kuznyechik_linear_table[i][in[i - 1U]];
    }
    out[0] = mixed;
}

/** @brief  Linear transformation L of the standard: 16 rounds of R. */
static void transform_l(uint8_t block[GOST_KUZNYECHIK_BLOCK])
{
    uint8_t scratch[GOST_KUZNYECHIK_BLOCK];
    for (unsigned round = 0; round < 8U; round++) {
        transform_r(block, scratch);
        transform_r(scratch, block);
    }
}

/**
 *  @brief  One round of the inverse linear transform.
 *
 *  Byte i takes the value of byte i + 1 and byte 15 becomes the linear
 *  combination of the shifted values.
 */
static void transform_r_inverse(const uint8_t in[GOST_KUZNYECHIK_BLOCK], uint8_t out[GOST_KUZNYECHIK_BLOCK])
{
    uint8_t mixed = 0;
    for (unsigned i = 0; i < 15U; i++) {
        out[i] = in[i + 1U];
        mixed ^= kuznyechik_linear_table[i][in[i]];
    }
    mixed ^= kuznyechik_linear_table[15U][in[15U]];
    out[15U] = mixed;
}

/** @brief  Inverse linear transformation L^-1. */
static void transform_l_inverse(uint8_t block[GOST_KUZNYECHIK_BLOCK])
{
    uint8_t scratch[GOST_KUZNYECHIK_BLOCK];
    for (unsigned round = 0; round < 8U; round++) {
        transform_r_inverse(block, scratch);
        transform_r_inverse(scratch, block);
    }
}

/**
 *  @brief  Iterative constant C_i of the key schedule: L(Vec(i)).
 */
static void schedule_constant(unsigned index, uint8_t out[GOST_KUZNYECHIK_BLOCK])
{
    memset(out, 0, GOST_KUZNYECHIK_BLOCK);
    out[15U] = (uint8_t)index;
    transform_l(out);
}

gost_status_t gost_kuznyechik_init(gost_kuznyechik_t *ctx, const uint8_t key[GOST_KUZNYECHIK_KEY])
{
    if (ctx == NULL || key == NULL) {
        return GOST_ERR_PARAM;
    }
    uint8_t k1[GOST_KUZNYECHIK_BLOCK];
    uint8_t k2[GOST_KUZNYECHIK_BLOCK];
    memcpy(k1, key, GOST_KUZNYECHIK_BLOCK);
    memcpy(k2, key + GOST_KUZNYECHIK_BLOCK, GOST_KUZNYECHIK_BLOCK);
    memcpy(ctx->round_keys[0], k1, GOST_KUZNYECHIK_BLOCK);
    memcpy(ctx->round_keys[1], k2, GOST_KUZNYECHIK_BLOCK);

    uint8_t feedback[GOST_KUZNYECHIK_BLOCK];
    uint8_t constant[GOST_KUZNYECHIK_BLOCK];
    unsigned constant_index = 1U;
    for (unsigned group = 0; group < 4U; group++) {
        for (unsigned step = 0; step < 8U; step++) {
            schedule_constant(constant_index, constant);
            constant_index++;
            for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
                feedback[i] = (uint8_t)(k1[i] ^ constant[i]);
            }
            transform_s(feedback);
            transform_l(feedback);
            /* Feistel step: (k1, k2) <- (feedback ^ k2, k1). */
            for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
                feedback[i] = (uint8_t)(feedback[i] ^ k2[i]);
            }
            memcpy(k2, k1, GOST_KUZNYECHIK_BLOCK);
            memcpy(k1, feedback, GOST_KUZNYECHIK_BLOCK);
        }
        memcpy(ctx->round_keys[2U * group + 2U], k1, GOST_KUZNYECHIK_BLOCK);
        memcpy(ctx->round_keys[2U * group + 3U], k2, GOST_KUZNYECHIK_BLOCK);
    }
    return GOST_OK;
}

gost_status_t gost_kuznyechik_encrypt_block(const gost_kuznyechik_t *ctx, const uint8_t in[GOST_KUZNYECHIK_BLOCK],
                                            uint8_t out[GOST_KUZNYECHIK_BLOCK])
{
    if (ctx == NULL || in == NULL || out == NULL) {
        return GOST_ERR_PARAM;
    }
    uint8_t block[GOST_KUZNYECHIK_BLOCK];
    memcpy(block, in, GOST_KUZNYECHIK_BLOCK);
    for (unsigned round = 0; round < GOST_KUZNYECHIK_ROUNDS - 1U; round++) {
        for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
            block[i] ^= ctx->round_keys[round][i];
        }
        transform_s(block);
        transform_l(block);
    }
    for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
        block[i] ^= ctx->round_keys[GOST_KUZNYECHIK_ROUNDS - 1U][i];
    }
    memcpy(out, block, GOST_KUZNYECHIK_BLOCK);
    return GOST_OK;
}

gost_status_t gost_kuznyechik_decrypt_block(const gost_kuznyechik_t *ctx, const uint8_t in[GOST_KUZNYECHIK_BLOCK],
                                            uint8_t out[GOST_KUZNYECHIK_BLOCK])
{
    if (ctx == NULL || in == NULL || out == NULL) {
        return GOST_ERR_PARAM;
    }
    uint8_t block[GOST_KUZNYECHIK_BLOCK];
    memcpy(block, in, GOST_KUZNYECHIK_BLOCK);
    for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
        block[i] ^= ctx->round_keys[GOST_KUZNYECHIK_ROUNDS - 1U][i];
    }
    for (unsigned round = GOST_KUZNYECHIK_ROUNDS - 1U; round-- > 0U;) {
        transform_l_inverse(block);
        transform_s_inverse(block);
        for (unsigned i = 0; i < GOST_KUZNYECHIK_BLOCK; i++) {
            block[i] ^= ctx->round_keys[round][i];
        }
    }
    memcpy(out, block, GOST_KUZNYECHIK_BLOCK);
    return GOST_OK;
}
